import React, { useState, useMemo, useCallback, useEffect, useRef } from "react";
import "./App.css";
import {
  Bone,
  GraduationCap,
  BookOpen,
  Calculator,
  RotateCcw,
  AlertCircle,
  CheckCircle2,
  ChevronDown,
  Sparkles,
  Hourglass,
  X,
  PencilLine,
} from "lucide-react";

/* ============================================================================
   BEAM — حاسبة المعدل التراكمي | قسم تقنيات الأشعة
   ----------------------------------------------------------------------------
   بنية البيانات مفصولة تماماً عن منطق الحساب وعن واجهة العرض، بحيث تتم إضافة
   "المرحلة الثالثة" أو "المرحلة الرابعة" مستقبلاً بمجرد إضافة كائن جديد داخل
   CURRICULUM بنفس الشكل — الواجهة والحسابات تتكيّف تلقائياً دون أي تعديل.
   ============================================================================ */

/* ---------------------------------- 1. البيانات ---------------------------------- */

// كل تقدير يقابله متوسط درجات ثابت يُستخدم داخلياً فقط في الحساب (لا يُعرض للطالب)
const GRADE_OPTIONS = [
  { value: "", label: "اختر التقدير", tone: "empty" },
  { value: 95, label: "ممتاز", tone: "excellent" },
  { value: 85, label: "جيد جداً", tone: "vgood" },
  { value: 75, label: "جيد", tone: "good" },
  { value: 65, label: "متوسط", tone: "medium" },
  { value: 55, label: "مقبول", tone: "pass" },
];

// نطاقات تحويل المعدل النهائي إلى تقدير لفظي
const GRADE_BANDS = [
  { min: 90, label: "ممتاز", tone: "excellent" },
  { min: 80, label: "جيد جداً", tone: "vgood" },
  { min: 70, label: "جيد", tone: "good" },
  { min: 60, label: "متوسط", tone: "medium" },
  { min: 50, label: "مقبول", tone: "pass" },
  { min: 0, label: "راسب", tone: "fail" },
];

// أوزان المراحل ضمن المعدل التراكمي النهائي (10% / 20% / 30% / 40%)
// محفوظة للاستخدام المستقبلي فقط — لا تُطبَّق في هذا الإصدار
const STAGE_WEIGHTS = { 1: 1, 2: 2, 3: 3, 4: 4 };
const STAGE_WEIGHTS_DIVISOR = 10;

/**
 * هيكل بيانات المنهج الدراسي.
 * كل "مرحلة" تحتوي على "كورسات" (فصول دراسية)، وكل كورس يحتوي على مواد.
 * لإضافة مرحلة جديدة: أضف مفتاحاً جديداً بنفس الشكل بالأسفل.
 */
const CURRICULUM = {
  stage1: {
    order: 1,
    label: "المرحلة الأولى",
    courses: {
      course1: {
        label: "الكورس الأول",
        subjects: [
          { id: "s1c1-1", name: "تشريح الهيكل العظمي", units: 3 },
          { id: "s1c1-2", name: "الفيزياء العامة", units: 3 },
          { id: "s1c1-3", name: "علم الفسلجة العام", units: 3 },
          { id: "s1c1-4", name: "البايولوجي", units: 3 },
          { id: "s1c1-5", name: "الكيمياء العامة", units: 3 },
          { id: "s1c1-6", name: "مبادئ الحاسوب 1", units: 2 },
          { id: "s1c1-7", name: "حقوق الإنسان والديمقراطية", units: 2 },
          { id: "s1c1-8", name: "اللغة الإنكليزية", units: 3 },
        ],
      },
      course2: {
        label: "الكورس الثاني",
        subjects: [
          { id: "s1c2-1", name: "تشريح أجهزة الجسم", units: 3 },
          { id: "s1c2-2", name: "فيزياء الذرة", units: 3 },
          { id: "s1c2-3", name: "علم الفسلجة الوظيفي", units: 3 },
          { id: "s1c2-4", name: "البايولوجي الإشعاعي", units: 4 },
          { id: "s1c2-5", name: "أسس التمريض", units: 4 },
          { id: "s1c2-6", name: "المصطلحات الطبية", units: 2 },
          { id: "s1c2-7", name: "اللغة العربية", units: 2 },
        ],
      },
    },
  },
  stage2: {
    order: 2,
    label: "المرحلة الثانية",
    courses: {
      course1: {
        label: "الكورس الأول",
        subjects: [
          { id: "s2c1-1", name: "تقنيات أجهزة التصوير المقطعي المحوسب", units: 4 },
          { id: "s2c1-2", name: "تقنيات التصوير الشعاعي للأطراف السفلى", units: 4 },
          { id: "s2c1-3", name: "التشريح الشعاعي للأطراف السفلى", units: 4 },
          { id: "s2c1-4", name: "فحوصات شعاعية خاصة للجهاز الهضمي والعظام", units: 4 },
          { id: "s2c1-5", name: "أساسيات الفيزياء الشعاعية", units: 3 },
          { id: "s2c1-6", name: "أساسيات الوقاية من الإشعاع", units: 3 },
          { id: "s2c1-7", name: "جرائم نظام البعث في العراق", units: 2 },
          { id: "s2c1-8", name: "تطبيقات الحاسوب", units: 2 },
        ],
      },
      course2: {
        label: "الكورس الثاني",
        subjects: [
          { id: "s2c2-1", name: "تقنيات الأجهزة الشعاعية التقليدية", units: 4 },
          { id: "s2c2-2", name: "تقنيات التصوير الشعاعي للأطراف العليا", units: 4 },
          { id: "s2c2-3", name: "التشريح الشعاعي للأطراف العليا", units: 4 },
          { id: "s2c2-4", name: "فحوصات شعاعية خاصة للجهاز الصفراوي والتناسلي", units: 4 },
          { id: "s2c2-5", name: "فيزياء التصوير المقطعي المحوسب", units: 4 },
          { id: "s2c2-6", name: "اللغة العربية", units: 1 },
        ],
      },
    },
  },
};

/* -------------------------------- 2. منطق الحساب -------------------------------- */

// يحوّل كائن المرحلة إلى مصفوفة مواد مسطّحة (مستقلة عن الكورسات)
function getStageSubjects(stage) {
  return Object.values(stage.courses).flatMap((course) => course.subjects);
}

function getGradeInfo(score) {
  return GRADE_BANDS.find((band) => score >= band.min) || GRADE_BANDS[GRADE_BANDS.length - 1];
}

/**
 * معدل المرحلة = مجموع (درجة التقدير × الوحدات) ÷ مجموع الوحدات
 */
function calculateStageGPA(stage, gradesById) {
  const subjects = getStageSubjects(stage);
  const totals = subjects.reduce(
    (acc, subject) => {
      const score = Number(gradesById[subject.id]);
      acc.weightedSum += score * subject.units;
      acc.totalUnits += subject.units;
      return acc;
    },
    { weightedSum: 0, totalUnits: 0 }
  );
  return totals.totalUnits > 0 ? totals.weightedSum / totals.totalUnits : 0;
}

/**
 * جاهزة للاستخدام المستقبلي: تحسب المعدل التراكمي النهائي بأوزان المراحل
 * (1×المرحلة1 + 2×المرحلة2 + 3×المرحلة3 + 4×المرحلة4) ÷ 10
 * لا تُستدعى حالياً لعدم اكتمال بيانات جميع المراحل.
 */
function calculateCumulativeGPA(stageGpaByOrder) {
  const weightedSum = Object.entries(stageGpaByOrder).reduce(
    (sum, [order, gpa]) => sum + gpa * (STAGE_WEIGHTS[order] || 0),
    0
  );
  return weightedSum / STAGE_WEIGHTS_DIVISOR;
}

function findMissingSubjectIds(stage, gradesById) {
  return getStageSubjects(stage)
    .filter((subject) => !gradesById[subject.id])
    .map((subject) => subject.id);
}

/* ---------------------------------- 3. الواجهة ---------------------------------- */

// توقيع الخط العربي لمصمم الموقع — صورة مفرّغة الخلفية (PNG بترميز base64)
const SIGNATURE_LOGO = "data:image/png;base64,";

const STAGE_LIST = Object.entries(CURRICULUM).sort((a, b) => a[1].order - b[1].order);

export default function GpaCalculatorApp() {
  const [selectedStageKey, setSelectedStageKey] = useState(STAGE_LIST[0][0]);
  const [gradesByStage, setGradesByStage] = useState({});
  const [resultByStage, setResultByStage] = useState({});
  const [missingIds, setMissingIds] = useState([]);
  const [errorMessage, setErrorMessage] = useState("");
  const [showResult, setShowResult] = useState(false);
  const [openGradePickerId, setOpenGradePickerId] = useState(null);
  const closeResultRef = useRef(null);

  const stage = CURRICULUM[selectedStageKey];
  const gradesById = gradesByStage[selectedStageKey] || {};
  const result = resultByStage[selectedStageKey] || null;
  const stageSubjects = useMemo(() => getStageSubjects(stage), [stage]);

  const handleSelectStage = useCallback((key) => {
    setSelectedStageKey(key);
    setErrorMessage("");
    setMissingIds([]);
    setShowResult(false);
    setOpenGradePickerId(null);
  }, []);

  const handleGradeChange = useCallback(
    (subjectId, value) => {
      setGradesByStage((prev) => ({
        ...prev,
        [selectedStageKey]: { ...prev[selectedStageKey], [subjectId]: value },
      }));
      setMissingIds((prev) => prev.filter((id) => id !== subjectId));
      setOpenGradePickerId(null);
      if (errorMessage) setErrorMessage("");
    },
    [selectedStageKey, errorMessage]
  );

  const handleCalculate = useCallback(() => {
    const missing = findMissingSubjectIds(stage, gradesById);
    if (missing.length > 0) {
      setMissingIds(missing);
      setErrorMessage(
        `يرجى اختيار التقدير لجميع المواد قبل الحساب (${missing.length} مادة متبقية).`
      );
      setResultByStage((prev) => ({ ...prev, [selectedStageKey]: null }));
      setShowResult(false);
      return;
    }
    const gpa = calculateStageGPA(stage, gradesById);
    const info = getGradeInfo(gpa);
    const stageWeight = STAGE_WEIGHTS[stage.order] || 0;
    const weightPercent = stageWeight * STAGE_WEIGHTS_DIVISOR;
    const contribution = (gpa * stageWeight) / STAGE_WEIGHTS_DIVISOR;
    setErrorMessage("");
    setMissingIds([]);
    setResultByStage((prev) => ({
      ...prev,
      [selectedStageKey]: { gpa, ...info, weightPercent, contribution },
    }));
    setShowResult(true);
  }, [stage, gradesById, selectedStageKey]);

  const handleReset = useCallback(() => {
    setGradesByStage((prev) => ({ ...prev, [selectedStageKey]: {} }));
    setResultByStage((prev) => ({ ...prev, [selectedStageKey]: null }));
    setMissingIds([]);
    setErrorMessage("");
    setShowResult(false);
    setOpenGradePickerId(null);
  }, [selectedStageKey]);

  const handleCloseResult = useCallback(() => setShowResult(false), []);

  useEffect(() => {
    if (!showResult) return undefined;

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    closeResultRef.current?.focus();

    const handleKeyDown = (event) => {
      if (event.key === "Escape") handleCloseResult();
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => {
      document.body.style.overflow = previousOverflow;
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [showResult, handleCloseResult]);

  const isStageEmpty = stageSubjects.length === 0;
  const completedSubjects = stageSubjects.filter((subject) => gradesById[subject.id]).length;
  const completionPercent = stageSubjects.length
    ? Math.round((completedSubjects / stageSubjects.length) * 100)
    : 0;

  return (
    <div className="app-root" dir="rtl" lang="ar">
      <div className="shell">
        <div className="topbar">
          <div className="brand-lockup">
            <span className="brand-mark" aria-hidden="true">
              <Bone size={20} strokeWidth={2.2} />
            </span>
            <span className="brand-copy">
              <b>BEAM</b>
              <small>قسم تقنيات الأشعة</small>
            </span>
          </div>
          <span className="edition-tag">إصدار الطلبة · 2026</span>
        </div>

        <header className="hero-grid">
          <div className="hero-main">
            <div className="hero-orbit" aria-hidden="true">
              <span></span><span></span><span></span>
            </div>
            <div className="hero-content">
              <div className="hero-eyebrow"><span></span> حاسبة أكاديمية دقيقة</div>
              <h1>حاسبة<br /><em>المعدل التراكمي</em></h1>
              <p>اختر المرحلة الدراسية، ثم حدّد تقديرك في كل مادة لاحتساب معدلك بدقة</p>
            </div>
          </div>

          <div className="hero-side" aria-label={`تقدم ${stage.label}`}>
            <span className="stage-kicker">المرحلة الحالية</span>
            <strong className="stage-number">0{stage.order}</strong>
            <div className="stage-side-bottom">
              <span>{stage.label}</span>
              <div className="mini-progress"><i style={{ width: `${completionPercent}%` }} /></div>
              <small>{completedSubjects} من {stageSubjects.length} مادة</small>
            </div>
          </div>
        </header>

        <section className="stage-picker">
          <div className="section-intro">
            <div>
              <span className="section-index">01</span>
              <h2>اختر المرحلة الدراسية</h2>
            </div>
            <p>كل مرحلة تحتفظ باختياراتها ونتيجتها بشكل مستقل</p>
          </div>
          <nav className="stage-tabs" role="tablist" aria-label="اختيار المرحلة الدراسية">
            {STAGE_LIST.map(([key, s]) => (
              <button
                key={key}
                role="tab"
                aria-selected={selectedStageKey === key}
                className={`stage-tab ${selectedStageKey === key ? "active" : ""}`}
                onClick={() => handleSelectStage(key)}
              >
                <span className="tab-number">0{s.order}</span>
                <span className="tab-label">
                  <GraduationCap size={18} strokeWidth={2} aria-hidden="true" />
                  {s.label}
                </span>
                <span className="tab-state">{selectedStageKey === key ? "محددة" : "اختيار"}</span>
              </button>
            ))}
          </nav>
        </section>

        {isStageEmpty ? (
          <div className="empty-stage">
            <div className="icon-chip">
              <Hourglass size={22} strokeWidth={1.8} aria-hidden="true" />
            </div>
            <h3>بيانات {stage.label} قيد الإضافة</h3>
            <p>سيتم تفعيل مواد هذه المرحلة قريباً. يمكنك حالياً احتساب معدل المرحلة الأولى.</p>
          </div>
        ) : (
          <div className="calculator-layout">
            <main className="courses-column">
              <div className="section-intro courses-intro">
                <div>
                  <span className="section-index">02</span>
                  <h2>أدخل تقديرات المواد</h2>
                </div>
                <p>{stageSubjects.length} مادة ضمن {Object.keys(stage.courses).length} كورسات</p>
              </div>

              {errorMessage && (
                <div className="error-banner" role="alert">
                  <span className="error-icon"><AlertCircle size={19} strokeWidth={2.2} aria-hidden="true" /></span>
                  <span>{errorMessage}</span>
                </div>
              )}

              {Object.entries(stage.courses).map(([courseKey, course], courseIndex) => (
                <section className="course-card" key={courseKey}>
                  <div className="course-head">
                    <div className="course-title">
                      <span className="icon-chip"><BookOpen size={17} strokeWidth={2} aria-hidden="true" /></span>
                      <div><small>الكورس 0{courseIndex + 1}</small><h3>{course.label}</h3></div>
                    </div>
                    <span className="subject-count">{course.subjects.length} مواد</span>
                  </div>

                  {course.subjects.map((subject) => {
                    const selectedGrade = GRADE_OPTIONS.find(
                      (option) => String(option.value) === String(gradesById[subject.id] || "")
                    ) || GRADE_OPTIONS[0];

                    return (
                      <div
                        className={`subject-row ${missingIds.includes(subject.id) ? "missing" : ""} ${gradesById[subject.id] ? "has-value" : ""}`}
                        key={subject.id}
                      >
                        <div className="subject-copy">
                          <span className="status-dot" aria-hidden="true" />
                          <span className="subject-name">{subject.name}</span>
                        </div>

                        <div
                          className="grade-picker"
                          data-tone={selectedGrade.tone}
                          onBlur={(event) => {
                            if (!event.currentTarget.contains(event.relatedTarget)) {
                              setOpenGradePickerId(null);
                            }
                          }}
                        >
                          <button
                            type="button"
                            className="grade-trigger"
                            aria-haspopup="listbox"
                            aria-expanded={openGradePickerId === subject.id}
                            aria-label={`التقدير في مادة ${subject.name}: ${selectedGrade.label}`}
                            onClick={() => setOpenGradePickerId((current) => current === subject.id ? null : subject.id)}
                          >
                            <span className="grade-color" aria-hidden="true" />
                            <span>{selectedGrade.label}</span>
                            <ChevronDown size={16} className="chevron" aria-hidden="true" />
                          </button>

                          {openGradePickerId === subject.id && (
                            <div className="grade-menu" role="listbox" aria-label={`خيارات التقدير لمادة ${subject.name}`}>
                              {GRADE_OPTIONS.slice(1).map((option, optionIndex) => (
                                <button
                                  type="button"
                                  role="option"
                                  aria-selected={String(option.value) === String(selectedGrade.value)}
                                  className="grade-option"
                                  data-tone={option.tone}
                                  key={option.value}
                                  onClick={() => handleGradeChange(subject.id, String(option.value))}
                                >
                                  <span className="grade-option-dot" aria-hidden="true" />
                                  <span>{option.label}</span>
                                  <i className="grade-option-meter" style={{ "--grade-level": 5 - optionIndex }} aria-hidden="true" />
                                </button>
                              ))}
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </section>
              ))}

              <section className="calculation-panel" aria-label="حساب المعدل">
                <div className="calculation-copy">
                  <div className="progress-card-head">
                    <span>جاهزية الحساب</span>
                    <strong>{completionPercent}٪</strong>
                  </div>
                  <div className="progress-track" aria-hidden="true"><i style={{ width: `${completionPercent}%` }} /></div>
                  <p><b>{completedSubjects}</b> من أصل <b>{stageSubjects.length}</b> مادة تم اختيار تقديرها</p>
                </div>
                <div className="actions">
                  <button className="btn btn-primary" onClick={handleCalculate}>
                    <Calculator size={20} strokeWidth={2.2} aria-hidden="true" />
                    <span>احسب المعدل</span>
                  </button>
                  <button className="btn btn-secondary" onClick={handleReset}>
                    <RotateCcw size={18} strokeWidth={2.2} aria-hidden="true" />
                    <span>إعادة تعيين</span>
                  </button>
                </div>
              </section>
            </main>
          </div>
        )}

        <footer className="site-footer">
          <div className="footer-line"><span>BEAM</span><i /></div>
          <div className="signature-wrap">
            <div>
              <span className="signature-label">إعداد الطالب</span>
            </div>
            <img src={SIGNATURE_LOGO} alt="توقيع مقتدى الكناني" className="signature-img" />
          </div>
        </footer>
      </div>

      {showResult && result && (
        <div className="result-overlay" role="presentation" onMouseDown={handleCloseResult}>
          <section
            className="result-dialog"
            role="dialog"
            aria-modal="true"
            aria-labelledby="result-dialog-title"
            onMouseDown={(event) => event.stopPropagation()}
          >
            <button
              type="button"
              className="dialog-close"
              aria-label="إغلاق النتيجة"
              onClick={handleCloseResult}
              ref={closeResultRef}
            >
              <X size={20} strokeWidth={2.2} aria-hidden="true" />
            </button>

            <div className="result-topline">
              <span id="result-dialog-title">النتيجة النهائية</span>
              <CheckCircle2 size={19} strokeWidth={2} aria-hidden="true" />
            </div>

            <div className="result-gauge" aria-label={`المعدل ${result.gpa.toFixed(2)} من 100`}>
              <svg viewBox="0 0 120 120" aria-hidden="true">
                <circle className="gauge-track" cx="60" cy="60" r="48" />
                <circle
                  className="gauge-progress"
                  cx="60"
                  cy="60"
                  r="48"
                  pathLength="100"
                  style={{
                    "--score-offset": 100 - Math.min(result.gpa, 100),
                    "--gauge-color": `var(--tone-${result.tone})`,
                  }}
                />
              </svg>
              <div className="gauge-inner">
                <strong>{result.gpa.toFixed(2)}</strong>
                <small>من 100</small>
              </div>
            </div>

            <div className="result-title">معدل {stage.label}</div>
            <div
              className="result-label"
              style={{
                color: `var(--tone-${result.tone})`,
                background: `color-mix(in srgb, var(--tone-${result.tone}) 15%, transparent)`,
                borderColor: `color-mix(in srgb, var(--tone-${result.tone}) 45%, transparent)`,
              }}
            >
              <Sparkles size={14} aria-hidden="true" />
              {result.label}
            </div>

            <div className="contribution-box">
              <div className="contribution-row">
                <span>المساهمة التراكمية<br /><small>{result.weightPercent}٪ لـ{stage.label}</small></span>
                <strong>{result.contribution.toFixed(3)}</strong>
              </div>
              <p className="contribution-note">
                أي أن معدل {stage.label} ({result.gpa.toFixed(2)}) يُحتسب ×{STAGE_WEIGHTS[stage.order]} ثم يُقسم على 10 ضمن معادلة المعدل التراكمي النهائي.
              </p>
            </div>

            <button type="button" className="edit-grades-btn" onClick={handleCloseResult}>
              <PencilLine size={17} strokeWidth={2} aria-hidden="true" />
              تعديل التقديرات
            </button>
          </section>
        </div>
      )}
    </div>
  );
}
